def count_odd_digit_numbers(N):
    count = 0
    d = 1
    while 10**(d-1) <= N:
        if d % 2 == 1:
            start = 10**(d-1)
            end = min(10**d - 1, N)
            count += end - start + 1
        d += 1
    return count

